  // px = (u / aspect + 0.5) * width, py = (0.5 - v) * height.
  let u = (frag.x / size.x - 0.5) * aspect;
  let v = 0.5 - frag.y / size.y;
  let lateral = g.right.xyz * u + g.up.xyz * v;

